describe('Accessibility - Reading Order', () => {
    beforeEach(() => {
        cy.visit('/'); // Replace with the actual URL of the page to test
    });

    it('should have the reading order match the visual order', () => {
        const expectedOrder = [
            'header', // Replace with actual selectors or text
            'main-content',
            'sidebar',
            'footer'
        ];

        cy.get('body').then(($body) => {
            const readingOrder = $body.find('*').toArray().map(el => el.innerText.trim()).filter(text => text);
            expect(readingOrder).to.deep.equal(expectedOrder);
        });
    });

    it('should handle missing elements gracefully', () => {
        const expectedOrder = [
            'header',
            'footer'
        ];

        cy.get('body').then(($body) => {
            const readingOrder = $body.find('*').toArray().map(el => el.innerText.trim()).filter(text => text);
            expect(readingOrder).to.deep.equal(expectedOrder);
        });
    });
});
